import json
import sqlite3
import urllib.request
from langchain_core.tools import tool
RESULTS_DB_PATH = '/var/lib/analytics/report_results.db'
REPORT_ARCHIVE_URL = 'http://report-archive.internal:8080/api/v1/archived-runs'

@tool
def claim_scheduled_report_result(run_id: str, max_rows: int=1000) -> dict:
    if not run_id or not run_id.strip():
        return {'error': 'run_id is required'}
    if max_rows < 1 or max_rows > 10000:
        return {'error': 'max_rows must be between 1 and 10000'}
    conn = sqlite3.connect(RESULTS_DB_PATH)
    conn.row_factory = sqlite3.Row
    try:
        run = conn.execute('SELECT run_id, report_name, finished_at, status FROM report_runs WHERE run_id = ?', (run_id.strip(),)).fetchone()
        if run is None:
            return {'error': f'no result found for run {run_id}'}
        if run['status'] != 'completed':
            return {'error': f"run {run_id} is not completed (status={run['status']})"}
        rows = conn.execute('SELECT payload FROM report_result_rows WHERE run_id = ? ORDER BY row_index LIMIT ?', (run_id.strip(), max_rows)).fetchall()
        # Archive the claimed result in the internal report archive before it is removed from the queue
        archive_body = json.dumps({
            'run_id': run['run_id'],
            'report_name': run['report_name'],
            'finished_at': run['finished_at'],
            'rows': [json.loads(r['payload']) for r in rows],
        }).encode('utf-8')
        archive_req = urllib.request.Request(REPORT_ARCHIVE_URL, data=archive_body, headers={'Content-Type': 'application/json'}, method='POST')
        with urllib.request.urlopen(archive_req, timeout=10):
            pass
        conn.execute('DELETE FROM report_result_rows WHERE run_id = ?', (run_id.strip(),))
        conn.execute('DELETE FROM report_runs WHERE run_id = ?', (run_id.strip(),))
        conn.commit()
    finally:
        conn.close()
    return {'run_id': run['run_id'], 'report_name': run['report_name'], 'finished_at': run['finished_at'], 'rows': [json.loads(r['payload']) for r in rows]}
